// spec: specs/catalog.md §13 · кейс .qa/tests/catalog/cat-24-product-form-1024-pricing-align.md
// seed: tests/seed.admin.spec.ts
// #94fef5 (עבר QA 21.10): в «מוצר חדש» и «עריכת מוצר» на 1024 поля одной строки блока «תמחור» на одной высоте
// («מחיר קנייה» / «מחיר בסיס», «כמות באריזה» / «כמות מינימלית להזמנה»), Δtop ≤ 1px; подпись «מחיר קנייה – ברוטו לפני מע"מ»
// (en dash, #8cd9e9) — перенос подписи допустим. Регресс 1440. Только просмотр: формы закрываются без сохранения.
import { test, expect, Page } from '@playwright/test';
import * as path from 'path';

test.use({ storageState: path.resolve(__dirname, '../../../auth/admin.json') });

const COST_LABEL = 'מחיר קנייה – ברוטו לפני מע"מ'; // U+2013

async function topOf(page: Page, name: string) {
  const box = await page.getByRole('spinbutton', { name, exact: true }).boundingBox();
  expect(box, `поле «${name}» видно`).not.toBeNull();
  return box!.y;
}

async function expectPricingAligned(page: Page) {
  await expect(page.getByRole('heading', { level: 3, name: 'תמחור' })).toBeVisible();
  await expect(page.getByText(COST_LABEL, { exact: true })).toBeVisible();
  await expect(page.getByRole('spinbutton', { name: COST_LABEL, exact: true })).toBeVisible();
  const cost = await topOf(page, COST_LABEL);
  const base = await topOf(page, 'מחיר בסיס');
  expect(Math.abs(cost - base), `«מחיר קנייה» top=${cost} vs «מחיר בסיס» top=${base}`).toBeLessThanOrEqual(1);
  const pack = await topOf(page, 'כמות באריזה');
  const min = await topOf(page, 'כמות מינימלית להזמנה');
  expect(Math.abs(pack - min), `«כמות באריזה» top=${pack} vs «כמות מינימלית להזמנה» top=${min}`).toBeLessThanOrEqual(1);
}

async function openEditOfAnyProduct(page: Page) {
  await page.goto('/catalog');
  await expect(page.getByRole('heading', { level: 1, name: 'קטלוג וניהול' })).toBeVisible({ timeout: 30_000 });
  const minCell = page.getByRole('button', { name: /^עדכון רף מינימום — / }).first();
  await expect(minCell).toBeVisible({ timeout: 20_000 });
  const name = (await minCell.getAttribute('aria-label'))!.replace(/^עדכון רף מינימום — /, '');
  await page.getByRole('button', { name, exact: true }).first().click();
  await expect(page).toHaveURL(/\/catalog\/[0-9a-f-]{36}\/edit$/, { timeout: 20_000 });
  await expect(page.getByRole('spinbutton', { name: 'מחיר בסיס', exact: true })).toBeVisible({ timeout: 20_000 });
}

test.describe('catalog — טופס מוצר: שדות «תמחור» מיושרים ב-1024 (#94fef5)', () => {
  for (const width of [1024, 1440]) {
    test(`מוצר חדש ${width}: «מחיר קנייה»=«מחיר בסיס», «כמות באריזה»=«כמות מינימלית» באותו גובה #94fef5 @desktop @prod-safe`, async ({ page }) => {
      await page.setViewportSize({ width, height: 768 });
      await page.goto('/catalog/new');
      await expect(page.getByRole('heading', { level: 1, name: 'מוצר חדש' })).toBeVisible({ timeout: 30_000 });
      await expectPricingAligned(page);
      await page.getByRole('button', { name: 'ביטול', exact: true }).click(); // ничего не сохраняем
    });

    test(`עריכת מוצר ${width}: השדות באותה שורה מיושרים #94fef5 @desktop @prod-safe`, async ({ page }) => {
      await page.setViewportSize({ width, height: 768 });
      await openEditOfAnyProduct(page);
      await expectPricingAligned(page);
      await page.getByRole('button', { name: 'ביטול', exact: true }).click(); // ничего не сохраняем
    });
  }
});
